#include <stdio.h>
#include "radial_cases.h"
#include "guidance_acceleration.h"
#include "projection_cases.h"
#include "acceleration_prefix.h"
static p66_trig_scratch trig;static p66_rotation_scratch rotation;static agc_dp afc;static agc_word cdu[3];
static void emit(radial_case *c,agc_dp tau,uint16_t n,uint8_t step,uint8_t stage,unsigned status){uint16_t w[RA_WORDS];unsigned i;ra_words(c,w);printf("%u %u %u %u",n,step,stage,status);for(i=0;i<RA_WORDS;++i)printf(" %u",w[i]);printf(" %u %u %u %u %u %u %u",tau.high,tau.low,trig.buf2.high,trig.buf2.low,trig.polish,trig.tem2,trig.tem3);for(i=0;i<6u;++i)printf(" %u",trig.cduspot[i]);for(i=0;i<6u;++i)printf(" %u",trig.sin[i]);for(i=0;i<6u;++i)printf(" %u",trig.cos[i]);for(i=0;i<3u;++i)printf(" %u",cdu[i]);printf(" %u %u %u %u\n",rotation.dex2,rotation.rtnsaver,afc.high,afc.low);}
int main(void){uint16_t n;for(n=0;n<RA_CASES;++n){radial_case c;agc_dp tau=acc_prefix_time(n);uint8_t step;ra_prepare(&c,n);for(step=0;step<ra_steps(n);++step){projection_case seed;unsigned status;uint8_t i;p66_preparation *s=&c.previous.previous.previous.previous.previous.previous.preparation;p66_scale_scratch *sc=&c.previous.previous.previous.previous.previous.previous.scratch;p66_elapsed_state *el=&c.previous.previous.previous.previous.elapsed;p66_divide_scratch *d=&c.previous.previous.previous.scratch;p66_pushdown *push=&c.previous.previous.previous.previous.previous.push;pj_input(&seed,n);trig=seed.previous.trig;rotation=seed.rotation;afc=seed.afc;for(i=0;i<3u;++i)cdu[i]=seed.previous.cdu[i];ra_next(&c,n,step);if(ra_integrated(n))ra_prefix(&c,n);emit(&c,tau,n,step,0,0);status=(unsigned)ra_apply(&c);emit(&c,tau,n,step,1,status);if(status!=P66_RADIAL_ALARM_1302)status=(unsigned)p66_acceleration(s,sc,el,d,&c.norm,push,&tau,c.previous.previous.gravity);emit(&c,tau,n,step,2,status);if(status!=P66_ACCELERATION_ALARM_1302){status=(unsigned)p66_projection_dot(s,sc,el,d,&c.norm,push,&trig,&rotation,cdu);emit(&c,tau,n,step,3,status);status=(unsigned)p66_projection_store(s,&c.norm,push);emit(&c,tau,n,step,4,status);status=(unsigned)p66_projection_acceleration(s,sc,el,d,&c.norm,push,&afc);emit(&c,tau,n,step,5,status);}}}return 0;}
